const s=input.state,e=input.event;
const NAME={amber:'Янтарь',mel:'Мел'};
const OPS={quiz:3,puzzle:2,hint:-5};
const LABELS={quiz:'Викторина',puzzle:'Пазл',hint:'Подсказка'};
function two(n){return (n<10?'0':'')+n;}
function fmt(ts){const d=new Date(ts);return two(d.getHours())+':'+two(d.getMinutes());}
function sync(){s.amberText=s.amberScore+' очк.';s.melText=s.melScore+' очк.';s.hasItems=s.items.length>0;s.empty=!s.hasItems;}
if(e.type==='action'){
 const a=e.actionId;
 if(a==='team'){s.team=e.value;s.noticeVisible=false;s.notice='';}
 if(OPS[a]!==undefined){
  const delta=OPS[a],key=s.team==='mel'?'mel':'amber';
  const cur=key==='amber'?s.amberScore:s.melScore;
  if(cur+delta<0){
   s.notice='Подсказка стоит 5 очков, а у команды «'+NAME[key]+'» только '+cur+'. В долг не выдаём.';
   s.noticeVisible=true;
  }else{
   const next=cur+delta;
   if(key==='amber')s.amberScore=next;else s.melScore=next;
   if(s.items.length<100){
    s.items.push({id:'e'+s.nextId,teamKey:key,team:NAME[key],deltaText:(delta>0?'+':'-')+Math.abs(delta),detail:LABELS[a]+' · '+fmt(Date.now())+' · баланс '+next});
    s.nextId=s.nextId+1;
   }
   s.noticeVisible=false;s.notice='';
  }
 }
 if(a==='undo'&&s.items.length>0){
  const it=s.items[s.items.length-1];
  const num=parseInt(it.deltaText.slice(1),10);
  const delta=it.deltaText.charAt(0)==='-'?-num:num;
  if(it.teamKey==='amber')s.amberScore=s.amberScore-delta;else s.melScore=s.melScore-delta;
  s.items=s.items.slice(0,s.items.length-1);
  s.noticeVisible=false;s.notice='';
 }
 sync();
}
return {state:s};
